import * as React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Box, Button, Container } from '@mui/material';
import DownloadIcon from '@mui/icons-material/Download';
import MenuIcon from '@mui/icons-material/Menu';
import Pdf from '../assets/Resume.pdf';

export default function SideBar() {
    const [open, setOpen] = React.useState(false)
    const location = useLocation();
    
    const scrollToSection = (id) => {
        const section = document.getElementById(id);
        section?.scrollIntoView({ 
            behavior: 'smooth',
            block: 'start',
        });
        handleOpen()
    }

    const handleOpen = () => {
        if (open) setOpen(false)
        else setOpen(true)
    }

    const showPDF = () => {
        window.open(Pdf, "_blank")
    }

    return(
        <>
            <Button 
                variant='text' 
                onClick={() => handleOpen()}
                sx={{
                    visibility: 'hidden',
                    '@media (max-width: 1000px)': {
                        visibility: 'visible',
                        position: 'fixed',
                        top: 0,
                        right: 0,
                        width: '5vw',
                        transition: '0.5s',
                        visibility: open ? 'hidden' : 'visible',
                    }
                    
                }}
            >
                <MenuIcon sx={{scale: 1.5}} />
            </Button>
            
            <Box
                sx={{
                    position: 'fixed',
                    visibility: 'hidden',
                    '@media (max-width: 1000px)': {
                        visibility: 'visible',
                        minWidth: '50vw',
                        minHeight: '100vh',
                        backgroundColor: 'rgba(14, 12, 24, 0.7)', // var(--background-color)
                        backdropFilter: 'blur(5px)',
                        zIndex: 1000,
                        boxShadow: open ? '1px 0px 9px black': 'none',
                        top: '0',
                        transition: '0.5s',
                        right: open ? '0': '-1000px',
                    },
                }}
            >
                <Container
                    sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'space-around',
                        minWidth: '50vw',
                        minHeight: '70vh',
                        marginTop: '10vh',
                    }}
                >
                    <Button variant='text' onClick={() => handleOpen()}><MenuIcon sx={{scale: 1.5}}/></Button>
                    <Button 
                        component={Link} to='/' 
                        variant='text' 
                        sx={{
                            color: location.pathname === '/'
                                ? "var(--highlight-color-2)"
                                : "var(--text-color)"
                        }}
                    >
                        Profile
                    </Button>
                    <Button 
                        component={Link} to='/extra' variant='text'
                        sx={{
                            color: location.pathname === '/extra'
                                ? "var(--highlight-color-2)"
                                : "var(--text-color)"
                        }}
                    >
                        Extra
                    </Button>
                    <Button 
                        variant='text' onClick={() => showPDF()}
                        startIcon={<DownloadIcon/>}
                        sx={{
                            color: "var(--text-color)",
                            border: 1,
                        }}
                    >
                        Resume
                    </Button>
                </Container>
            </Box>
        </>
        
    );
}